CREATE TABLE public.weekly_results(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),league_id uuid NOT NULL REFERENCES public.leagues(id),team_id uuid NOT NULL REFERENCES public.teams(id),week_start date NOT NULL,points numeric NOT NULL,UNIQUE(team_id,week_start)); GRANT SELECT ON public.weekly_results TO authenticated; GRANT ALL ON public.weekly_results TO service_role; ALTER TABLE public.weekly_results ENABLE ROW LEVEL SECURITY; CREATE POLICY weekly_read ON public.weekly_results FOR SELECT TO authenticated USING(public.league_member(league_id));
CREATE FUNCTION public.finalize_fantasy_week(lid uuid,week_start date) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l leagues;t teams;p numeric;ids uuid[];scores numeric[];i int;n int; BEGIN IF NOT public.league_commissioner(lid) THEN RAISE EXCEPTION 'Only the commissioner can finalize a week'; END IF; SELECT * INTO l FROM leagues WHERE id=lid FOR UPDATE; IF EXISTS(SELECT 1 FROM weekly_results wr WHERE wr.league_id=lid AND wr.week_start=finalize_fantasy_week.week_start) THEN RAISE EXCEPTION 'This week was already finalized'; END IF; IF NOT EXISTS(SELECT 1 FROM game_boxscores WHERE league_id=lid AND game_date>=week_start AND game_date<week_start+7) THEN RAISE EXCEPTION 'Record game box scores for this week first'; END IF; ids:=ARRAY[]::uuid[];scores:=ARRAY[]::numeric[]; FOR t IN SELECT * FROM teams WHERE league_id=lid ORDER BY draft_order LOOP SELECT coalesce(sum(b.pts*(l.scoring->>'pts')::numeric+b.reb*(l.scoring->>'reb')::numeric+b.ast*(l.scoring->>'ast')::numeric+b.stl*(l.scoring->>'stl')::numeric+b.blk*(l.scoring->>'blk')::numeric+b.turnovers*(l.scoring->>'turnovers')::numeric),0) INTO p FROM roster_slots rs JOIN game_boxscores b ON b.player_id=rs.player_id AND b.league_id=lid WHERE rs.team_id=t.id AND rs.slot<=3 AND b.game_date>=week_start AND b.game_date<week_start+7; INSERT INTO weekly_results(league_id,team_id,week_start,points) VALUES(lid,t.id,week_start,p); UPDATE teams SET total_points=total_points+p WHERE id=t.id; ids:=array_append(ids,t.id);scores:=array_append(scores,p); END LOOP; n:=array_length(ids,1);i:=1; WHILE i<n LOOP UPDATE teams SET wins=wins+CASE WHEN scores[i]>scores[i+1] THEN 1 ELSE 0 END,losses=losses+CASE WHEN scores[i]<scores[i+1] THEN 1 ELSE 0 END,ties=ties+CASE WHEN scores[i]=scores[i+1] THEN 1 ELSE 0 END WHERE id=ids[i]; UPDATE teams SET wins=wins+CASE WHEN scores[i+1]>scores[i] THEN 1 ELSE 0 END,losses=losses+CASE WHEN scores[i+1]<scores[i] THEN 1 ELSE 0 END,ties=ties+CASE WHEN scores[i+1]=scores[i] THEN 1 ELSE 0 END WHERE id=ids[i+1];i:=i+2; END LOOP; INSERT INTO league_activity(league_id,message) VALUES(lid,'Weekly matchup finalized for '||week_start::text); END $$; REVOKE ALL ON FUNCTION public.finalize_fantasy_week(uuid,date) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.finalize_fantasy_week(uuid,date) TO authenticated;